from pathlib import Path
import json,csv,statistics
S=Path(__file__).resolve().parent;ROOT=S.parent.parent;H=ROOT/'reports/R8-U-FOLD-20261111-v1'
def load(p):return json.loads(p.read_text())
def save(name,value):(S/name).write_text(json.dumps(value,indent=2,ensure_ascii=False)+'\n')
def metrics(r):
 scans=r['U_SCAN_DETAIL']['P'];m=r['PERF4_U_STATE']['P'][0];rounds=r['R8_U_FOLD_ROUND']['P'];scan=sum(x['u_scan_wall_time'] for x in scans);weights=sum(x['mle_weights_wall'] for x in scans);capture=sum(x['u_state_capture_wall'] for x in scans)
 return dict(P_wall_seconds=r['P']['wall_seconds'],V_wall_seconds=r['V']['wall_seconds'],U_scan_wall_seconds=scan,U_scan_cpu_seconds=sum(x['u_scan_cpu_time'] for x in scans),U_weights_wall_seconds=weights,U_capture_wall_seconds=capture,U_fold_wall_seconds=m['fold_wall_seconds'],U_fold_cpu_seconds=m['fold_cpu_seconds'],U1_materialization_wall_seconds=m['materialization_wall_seconds'],U1_materialization_cpu_seconds=m['materialization_cpu_seconds'],subsequent_fold_wall_seconds=m['fold_wall_seconds']-m['materialization_wall_seconds'],unmap_wall_seconds=m.get('unmap_wall_seconds',0),unmap_cpu_seconds=m.get('unmap_cpu_seconds',0),U_focused_wall_seconds=scan+weights+capture+m['fold_wall_seconds'],Sumcheck_wall_seconds=r['UNIFIED_SUMCHECK']['P'][0]['wall_seconds'],P_peak_RSS_KiB=r['P']['peak_rss_kib'],V_peak_RSS_KiB=r['V']['peak_rss_kib'],U_capacity_peak_bytes=m.get('mapped_capacity_peak_bytes',max(x.get('vector_capacity_bytes',0) for x in rounds)),U_final_retained_bytes=m.get('mapped_bytes',max(x.get('vector_capacity_bytes',0) for x in rounds)),U_final_live_bytes=m['live_bytes'],unmapped_tail_bytes=m.get('unmapped_tail_bytes',0),unmap_calls=m.get('unmap_calls',0),Original_read_bytes=sum(x['original_source_scalar_payload_bytes'] for x in scans)+32*m['original_read_coordinates'],proof_bytes=r['proof_bytes'])
def main():
 assert load(S/'EXPERIMENTS_RESULT.json')['success']
 names=[f'oneblock-{side}{i}' for i in range(1,4) for side in 'AB']+['full12-R9'];results={name:load(S/name/'RESULT.json') for name in names};raw={name:metrics(r) for name,r in results.items()};save('RAW_METRICS.json',raw)
 with (S/'RAW_METRICS.tsv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=['run']+list(next(iter(raw.values()))),delimiter='\t');w.writeheader();w.writerows(dict(run=k,**v) for k,v in raw.items())
 stats={}
 historical={f'Immediate{i}':metrics(load(H/f'oneblock-B{i}/RESULT.json')) for i in range(1,4)}|{f'Deferred{i}':metrics(load(H/f'oneblock-A{i}/RESULT.json')) for i in range(1,4)}
 historical['Full12Immediate']=metrics(load(H/'full12-immediate/RESULT.json'));save('R8_HISTORICAL_METRICS.json',historical)
 for key in raw['oneblock-A1']:
  groups={'R8_Immediate_current':[raw[f'oneblock-A{i}'][key] for i in range(1,4)],'R9_current':[raw[f'oneblock-B{i}'][key] for i in range(1,4)],'R8_Immediate_historical':[historical[f'Immediate{i}'][key] for i in range(1,4)],'R8_Deferred_historical':[historical[f'Deferred{i}'][key] for i in range(1,4)]}
  d={g:dict(median=statistics.median(v),min=min(v),max=max(v),samples=v) for g,v in groups.items()}
  a=d['R8_Immediate_current']['median'];b=d['R9_current']['median'];h=d['R8_Immediate_historical']['median'];d['R9_minus_current_R8']=b-a;d['change_percent_vs_current_R8']=100*(b-a)/a if a else None;d['change_percent_vs_historical_R8']=100*(b-h)/h if h else None;stats[key]=d
 save('AB_STATISTICS.json',stats)
 for name,r in results.items():
  folds=r['R8_U_FOLD_ROUND']['P'];scans=r['U_SCAN_DETAIL']['P'];assert len(folds)==len(scans)
  if r['mode']=='R9':
   assert all(x['original_read_elements']==0 for x in folds[1:]) and all(x['original_source_read_elements']==0 for x in scans[1:])
   assert all(folds[i]['mapped_bytes']<=folds[i-1]['mapped_bytes'] for i in range(1,len(folds)))
   assert sum(x['released_tail_bytes'] for x in folds)==folds[0]['mapped_bytes']-folds[-1]['mapped_bytes']
  with (S/name/'U_ROUNDS.tsv').open('w') as f:
   rows=[dict(**fold,scan_wall_seconds=scan['u_scan_wall_time'],scan_cpu_seconds=scan['u_scan_cpu_time'],Original_scan_bytes=scan['original_source_scalar_payload_bytes']) for fold,scan in zip(folds,scans)];w=csv.DictWriter(f,fieldnames=list(rows[0]),delimiter='\t');w.writeheader();w.writerows(rows)
 full=raw['full12-R9'];old=historical['Full12Immediate'];save('FULL12_COMPARISON.json',{k:dict(R8_historical=old[k],R9=full[k],difference=full[k]-old[k],change_percent=100*(full[k]-old[k])/old[k] if old[k] else None) for k in full})
 lines=['# R9 Immediate-only U Folding 实测报告','','已完成实现、Release 编译、相关测试、三组当前环境 Oneblock A/B 与 Full12 Prover/独立 Verifier。','', '`production_gate=BLOCKED_CRYPTOGRAPHIC_DESIGN`；`may_enter_stage2=false`。','', '## 时间比较','','主基准为 R8 Immediate。A1/B1/A2/B2/A3/B3 串行交替，A 使用修改前保存的 R8 二进制，B 使用当前 R9 二进制；相同参数、Statement、四线程、CPU affinity、协议 context。R8 Immediate 历史三次及 Deferred 历史三次作为额外参考。下表为三次中位数，秒；完整 min/max 和所有样本见 AB_STATISTICS.json。','', '| 指标 | R8 Immediate 历史 | R8 Immediate 当前复测 | R9 当前 | R9−当前 R8 | 变化 % | R8 Deferred 历史参考 |','|---|---:|---:|---:|---:|---:|---:|']
 for key in ['U1_materialization_wall_seconds','subsequent_fold_wall_seconds','unmap_wall_seconds','U_fold_wall_seconds','U_scan_wall_seconds','U_focused_wall_seconds','Sumcheck_wall_seconds','P_wall_seconds','V_wall_seconds']:
  d=stats[key];g=lambda n:d[n]['median'];delta=d['change_percent_vs_current_R8'];lines.append(f"| {key} | {g('R8_Immediate_historical'):.6f} | {g('R8_Immediate_current'):.6f} | {g('R9_current'):.6f} | {d['R9_minus_current_R8']:+.6f} | {delta:+.3f}% | {g('R8_Deferred_historical'):.6f} |" if delta is not None else f"| {key} | {g('R8_Immediate_historical'):.6f} | {g('R8_Immediate_current'):.6f} | {g('R9_current'):.6f} | {d['R9_minus_current_R8']:+.6f} | N/A | {g('R8_Deferred_historical'):.6f} |")
 lines+=['','正值表示 R9 更慢，负值表示 R9 更快。U 专项 = scan + MLE weights + capture + fold；fold 已包含 U1 初始化和 shrink/unmap，禁止重复加总。unmap_wall_seconds 包含 shrinkTo 的尾部析构和调用计量开销，属于后续 fold 的子项。三组样本无法单独证明小幅总耗时差异由 mmap 因果导致，系统噪声与其他阶段也会变化。','', '## Full12（各一次，历史对照）','','| 指标 | R8 Immediate 历史 | R9 | 差异 |','|---|---:|---:|---:|']
 for key in ['U1_materialization_wall_seconds','subsequent_fold_wall_seconds','unmap_wall_seconds','U_scan_wall_seconds','U_fold_wall_seconds','U_focused_wall_seconds','Sumcheck_wall_seconds','P_wall_seconds','V_wall_seconds','P_peak_RSS_KiB','U_capacity_peak_bytes','U_final_retained_bytes','U_final_live_bytes','unmapped_tail_bytes','unmap_calls','proof_bytes']:lines.append(f'| {key} | {old[key]:.6f} | {full[key]:.6f} | {full[key]-old[key]:+.6f} |')
 r=results['full12-R9'];fs=r['fs'];lines+=['',f"Full12 coverage {r['coverage_count']} 全部验证；proof SHA256 `{r['proof_sha256']}`。P/V transcript 与 challenge digest 一致。Full12 不是当前环境重复配对实验，不能将全部差异归因于 U 改造。",'', '## 实现与内存释放','','唯一生命周期为 Original → challenge 后直接构建 U1 → 原地折叠和 munmap 尾部。删除 Deferred/Auto、预算模块和六个模式/预算环境变量解析。capture 保留为空操作，u_streaming.cpp SHA 保持不变。Original 只借用，不修改不释放，读回调仅当次借用；descriptor 保留非 owning presence marker。','', 'FrBuffer 采用 MAP_PRIVATE|MAP_ANONYMOUS，按 sysconf 页大小对齐，检查乘法及取整溢出。每个 Fr placement new 构造；shrink 先析构尾部、更新 size，再释放整页。munmap 失败时保留原映射长度以正确 cleanup，状态 poison；noexcept cleanup 重试一次，持续失败 fail-stop (terminate)，不会静默继续或隐藏泄漏。不新增半尺寸数组，无 U 文件。','', '每轮实测有效字节、映射字节、RSS、峰值 RSS、已释放尾部字节及时间，见各 run/U_ROUNDS.tsv 和原始 R8_U_FOLD_ROUND 日志。页面粒度允许后期映射不变；最终每个 Segment 至少保留一页，所有映射在析构或 poison 时释放。进程 RSS 还包括 Original、K、witness 等，不能把 U 映射下降等同于整个 Prover 峰值同比下降。','', '## 验证与范围','','相关 CTest 18/18 通过，含 dense 全局/局部系数、端点、分类布局、独立协议测试和 blocks12 拒绝 guard。perf4 增加 mmap 分配失败、部分 Segment 分配失败、munmap 一次失败、Callback reader 异常、poison 禁用和全部映射释放、Original 不变、Original 读取仅第一 advance、实际 munmap 计数核对。Category callback owner 不延寿测试保留。FrBuffer move/self-move、析构、零长度、溢出通过独立内部类测试。','', '固定 RNG 有界协议测试：R8/R9 proof 逐字节一致，各由独立 Verifier 接受；见 TRANSCRIPT_EQUIVALENCE.json。真实 Oneblock 六次与 Full12 一次均独立 P/V，完整 opening 和 coverage 另行验证。随机会话之间不要求 proof 字节相同。','', 'CHANGED_FILES.json 列出八个修改文件和五个删除文件及哈希；R9-IMMEDIATE-ONLY-U.patch 为可审查源码差异。祖先 Git 不代表此未提交工作快照，git status 只显示整个目录未跟踪，不能用空 git diff 代替源码审查。baseline/ 保存修改前文件，历史 R8 数据未改动。SCOPE_AUDIT.json 核对全部 src 变化，未修改 Worker/调度/线程/Tile/PublicK/Transcript/Verifier/GKR/Lasso/Hyrax/模型。','', '远端 HEAD 两次核实为指定 fc4a386f695c84fe6e7e7cc68cbdc5c23f3a55e1；raw 源文件获取超时，随后 Git 对象下载许可被拒绝，因此不声称完整远端文件树已逐字节核实。实际实验身份以 SOURCE_BEFORE/FROZEN_SOURCE/PARAMETERS/二进制 SHA 为准。','', '## 限制','','Linux overcommit 下，mmap 成功后触页仍可能被 OOM Killer 终止；不能保证所有内存不足变为可捕获异常。此实现不设 RAM 预算、无提前内存准入、无 Deferred 回退。munmap 持续系统错误使用 fail-stop，不能保证在损坏进程中继续生成证明。','', 'RSS 采用进程 rusage 峰值和分轮 /proc/self/statm；共享 cgroup memory.current 只作背景采样，memory.peak 不可用或累计语义不能作为独立本次峰值。进程块 I/O 无法归因给 U；禁止把早期 /proc/io 样本零值解释成全程零物理 I/O。','', '工程正确性与性能验证不解除密码学设计门禁。']
 phases={}
 for label,log in [('R8_historical',ROOT/'logs/R8-U-FOLD-20261111-v1/full12-immediate-P.log'),('R9',ROOT/'logs'/S.name/'full12-R9-P.log')]:
  phases[label]={}
  for line in log.read_text().splitlines():
   if line.startswith('PHASE_CPU '):
    value=json.loads(line[len('PHASE_CPU '):]);phases[label][value['name']]=value['cpu_seconds']
 save('PHASE_CPU_COMPARISON.json',phases)
 lines+=['','## Full12 历史对照的环境变化证据','','这些阶段发生在 FoldedU 使用前且源码未改，其 CPU 时间也明显上升。该证据说明完整 P 历史差值不能作为 mmap 的单独因果估计。CPU 时间与 wall 时间不同，不将其直接相加解释 P wall 差值。','','| 阶段 | R8 历史 CPU 秒 | R9 CPU 秒 |','|---|---:|---:|']
 for name,seconds in phases['R9'].items():lines.append(f"| {name} | {phases['R8_historical'].get(name,0):.6f} | {seconds:.6f} |")
 (S/'FINAL_REPORT.zh-CN.md').write_text('\n'.join(lines)+'\n');save('STATUS.json',dict(implemented=True,tested=True,benchmarked=True,full12_verified=True,production_gate='BLOCKED_CRYPTOGRAPHIC_DESIGN',may_enter_stage2=False))
if __name__=='__main__':main()
